<template><div><section class="pricing-intro shell"><span class="eyebrow">Simple, family-friendly pricing</span><h1>Choose a plan that helps<br><em>your child keep growing.</em></h1><p>Start free and upgrade when you’re ready. Downloadable store resources remain separate, so you only buy what you need.</p><div class="billing-toggle"><button :class="{active:!yearly}" @click="yearly=false">Monthly</button><button :class="{active:yearly}" @click="yearly=true">Yearly <span>Save 20%</span></button></div></section><section class="pricing-grid shell"><article v-for="plan in plans" :key="plan.name" :class="['price-card',plan.color,{popular:plan.popular}]"><span v-if="plan.popular" class="popular-tag"><Sparkles/> Most popular</span><h2>{{plan.name}}</h2><p>{{plan.desc}}</p><div class="price"><strong>{{plan.price}}</strong><span v-if="plan.price!=='₦0'">/ month</span></div><small v-if="plan.price!=='₦0'">Billed {{yearly ? 'yearly' : 'monthly'}}</small><RouterLink class="button" :to="plan.name==='Free'?'/register':'/register'">{{plan.name==='Free'?'Start free':'Choose '+plan.name}}</RouterLink><ul><li v-for="feature in plan.features" :key="feature"><Check/>{{feature}}</li></ul></article></section><section class="pricing-note shell"><div><h3>Resources stay flexible.</h3><p>Subscriptions unlock learning and games. Store resources are one-time purchases, with special discounts for members.</p></div><RouterLink class="arrow-link" to="/resources">Browse resource store →</RouterLink></section></div></template>
